from pwn import remote
import numpy as np

def main():
    print("x y out")
    for x in np.linspace(-10, 10, 21):
        try:
            r = remote('misc.chal.csaw.io', 3001)
            r.recvuntil(b'Enter your input:')
            r.sendline(f"{x}\n0".encode())
            lines = []
            while True:
                try:
                    data = r.recv(timeout=0.5)
                    if not data:
                        break
                    lines += data.decode(errors='ignore').splitlines()
                except Exception:
                    break
            if lines:
                last = next((l for l in reversed(lines) if l.strip()), '')
            else:
                last = ''
            print(f"{x} 0 {last}")
            r.close()
        except Exception as e:
            print(f"{x} 0 EXCEPTION: {e}")

if __name__ == "__main__":
    main()

