from pwn import remote

# Binary search x transition for y=0 between -2 and -1.
def query(x, y):
    r = remote('misc.chal.csaw.io', 3001)
    r.recvuntil(b'Enter your input:')
    r.sendline(f"{x:.8f}\n{y:.8f}".encode())
    lines = b""
    while True:
        try:
            data = r.recv(timeout=0.5)
            if not data:
                break
            lines += data
        except Exception:
            break
    r.close()
    if b'Cool numbers' in lines:
        return 'cool', lines.decode(errors='ignore')
    elif b'Not cool numbers' in lines:
        return 'notcool', lines.decode(errors='ignore')
    else:
        return 'other', lines.decode(errors='ignore')

def main():
    lo = -2.0
    hi = -1.0
    # Find boundary where x for y=0 changes from not cool to cool.
    last_cat = None
    # Scan with greater precision
    print("Scanning decision boundary for x at y=0")
    for _ in range(24):
        mid = (lo + hi) / 2
        cat, msg = query(mid, 0)
        print(f"x={mid:.8f}, category={cat}, sample_output={msg.strip().splitlines()[-1] if msg.strip().splitlines() else ''}")
        if cat == 'cool':
            hi = mid
        else:
            lo = mid
        if abs(hi - lo) < 1e-5:
            break
    print(f"Approximate decision boundary at x={mid:.8f}, y=0")
    # Print output exactly at boundary and nearby values
    for delta in [-0.0002,-0.0001,0,0.0001,0.0002]:
        x = mid+delta
        cat, msg = query(x, 0)
        print(f"x={x:.8f}, category={cat}, final_output={msg.strip().splitlines()[-1] if msg.strip().splitlines() else ''}")
        if cat == 'cool' and cat != last_cat and (last_cat is not None):
            # Print full output as it transitions
            print(f"Full boundary output for x={x:.8f}:\n{msg}")
        last_cat = cat

if __name__ == "__main__":
    main()

