from pwn import remote

def get_category(x, y):
    try:
        r = remote('misc.chal.csaw.io', 3001)
        r.recvuntil(b'Enter your input:')
        r.sendline(f"{x:.8f}\n{y:.8f}".encode())
        lines = b""
        while True:
            try:
                data = r.recv(timeout=0.5)
                if not data:
                    break
                lines += data
            except Exception:
                break
        r.close()
    except Exception as e:
        return 'fail', str(e)
    if b'Cool numbers' in lines:
        return 'cool', lines.decode(errors='ignore')
    elif b'Not cool numbers' in lines:
        return 'notcool', lines.decode(errors='ignore')
    else:
        return 'other', lines.decode(errors='ignore')

# Sample multiple  fixed x across y, for y in (-2, 2) at fine steps; print results at transition.
def scan_axis(axis='y', n_points=6, yspan=(-2,2), xspan=(-2,2)):
    results = []
    for i in range(n_points+1):
        data = []
        if axis=='y':
            x = 0
            yvals = [yspan[0]+(yspan[1]-yspan[0])*j/(n_points-1) for j in range(n_points)]
            for y in yvals:
                lastcat = None
                # binary search around this y
                lo = y-0.01
                hi = y+0.01
                for _ in range(24):
                    mid = (lo+hi)/2
                    cat, msg = get_category(x, mid)
                    if cat == 'cool':
                        hi = mid
                    else:
                        lo = mid
                    if abs(hi-lo)<1e-5:
                        break
                # what is at boundary and below/above?
                outs = []
                for delta in [-0.001,-0.0005,0,0.0005,0.001]:
                    val = mid+delta
                    cat, msg = get_category(x, val)
                    outs.append((val,cat,msg.strip().splitlines()[-1] if msg.strip().splitlines() else ''))
                data.append((mid, outs))
            results.append((x,y,data))
        else:
            y = 0
            xvals = [xspan[0]+(xspan[1]-xspan[0])*j/(n_points-1) for j in range(n_points)]
            for x in xvals:
                lastcat = None
                lo = x-0.01
                hi = x+0.01
                for _ in range(24):
                    mid = (lo+hi)/2
                    cat, msg = get_category(mid, y)
                    if cat == 'cool':
                        hi = mid
                    else:
                        lo = mid
                    if abs(hi-lo)<1e-5:
                        break
                outs = []
                for delta in [-0.001,-0.0005,0,0.0005,0.001]:
                    val = mid+delta
                    cat, msg = get_category(val, y)
                    outs.append((val,cat,msg.strip().splitlines()[-1] if msg.strip().splitlines() else ''))
                data.append((mid, outs))
            results.append((x,y,data))
    return results

if __name__=="__main__":
    # y axis
    print("\n---- Probe along y axis at x=0 ----\n")
    ydata = scan_axis('y',6)
    for x,y,lst in ydata:
